keyframes:
@keyframes plyr-popup { 
  0% { opacity: 0.5; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@-webkit-keyframes spinner-grow { 
  0% { transform: scale(0); }
  50% { opacity: 1; transform: none; }
}

@keyframes spinner-grow { 
  0% { transform: scale(0); }
  50% { opacity: 1; transform: none; }
}

@keyframes moveText { 
  0% { transform: scaleX(1) translateX(105%); }
  98% { opacity: 1; }
  99% { transform: scaleX(1) translateX(-105%); opacity: 0; }
  100% { transform: scaleX(1) translateX(105%); opacity: 0; }
}
